#!/usr/bin/env python3
"""Writes the facts the instructions state about the code from the code itself.

A fact typed into a note goes stale ("three phones" when the sweep had four,
"screens 01 to 11" after two were deleted, a check table that named the wrong job).
So each such fact lives in a block the tool writes:

    <!-- generated by tool/gen_docs.py (NAME): run it with --fix, never edit by hand -->
    ...
    <!-- end generated -->

NAME is one of BLOCKS: the commands of a CLAUDE.md (each recipe's own comment in its
justfile, and the steps of a recipe that is only steps), the screens and the sizes
they are judged at (from the app and the tests), GitHub's required checks (from the
workflows and the ruleset, tool/github_checks.py) and the agents (their front matter).

    tool/gen_docs.py          fail when a block is not what the code says (in `just check`)
    tool/gen_docs.py --fix    rewrite every block
"""

import json
import re
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "tool"))
import github_checks  # noqa: E402

BLOCK = re.compile(
    r"(<!-- generated by tool/gen_docs\.py \((?P<name>[\w ]+)\): run it with --fix, never edit by hand -->\n)"
    r"(?P<body>.*?)(<!-- end generated -->)",
    re.S,
)
DOCUMENTS = [
    "CLAUDE.md",
    "backend/CLAUDE.md",
    "frontend/CLAUDE.md",
    "docs/claude-architecture.md",
]
# The recipes each CLAUDE.md names, in its order: (justfile they are described from, names).
COMMANDS = {
    "root": (
        "justfile",
        [
            "brief",
            "piece-check",
            "handover",
            "check",
            "test",
            "flutter-test",
            "samples",
            "gate-full",
            "heavy",
        ],
    ),
    "backend": (
        "backend/justfile",
        [
            "test-backend",
            "check-backend",
            "fix",
            "samples",
            "tap-budget",
            "server-timing",
            "harness-serve",
        ],
    ),
    "frontend": (
        "frontend/justfile",
        [
            "flutter-test",
            "analyze",
            "flutter-format-check",
            "gen",
            "gen-check",
            "look",
            "screens",
            "contact-sheet",
            "test-harness",
            "record-assets",
            "check-release",
            "skin-art",
            "flutter-golden-update",
        ],
    ),
}
WIDE = 100


def recipes(justfile: str) -> dict:
    out = subprocess.run(
        [
            "just",
            "--justfile",
            str(ROOT / justfile),
            "--working-directory",
            str(ROOT),
            "--dump",
            "--dump-format",
            "json",
        ],
        capture_output=True,
        text=True,
        check=True,
    ).stdout
    return json.loads(out)["recipes"]


def comment(justfile: str, name: str) -> str:
    """The comment block right above the recipe, as one text."""
    lines = (ROOT / justfile).read_text().splitlines()
    at = next(
        i
        for i, line in enumerate(lines)
        if re.match(rf"^@?{re.escape(name)}(?:\s[^:]*)?:(?!=)", line)
    )
    block = []
    while at > 0 and lines[at - 1].startswith("#"):
        at -= 1
        block.insert(0, lines[at].lstrip("#").strip())
    return " ".join(block).removeprefix("(frontend) ").removeprefix("(backend) ")


def first_sentence(text: str) -> str:
    sentence = re.split(r"(?<=[.)])\s+(?=[A-Z`(])", text)[0] if text else ""
    if len(sentence) > WIDE:
        sentence = sentence[: sentence.rfind(" ", 0, WIDE)] + " ..."
    return sentence


def steps(recipe: dict) -> list[str]:
    """The steps of a recipe that only runs other recipes and tools, else []."""
    found = []
    for line in recipe["body"]:
        text = "".join(
            part if isinstance(part, str) else "{{}}" for part in line
        ).strip()
        if m := re.fullmatch(r"\{\{\}\} ([\w-]+)(?: \{\{\}\})?", text):
            found.append(m[1])
        elif m := re.fullmatch(r"tool/(\w+)\.(?:py|sh)( --[\w-]+)?", text):
            found.append(m[1] + (m[2] or ""))
        else:
            return []
    return found


def commands(which: str) -> str:
    justfile, names = COMMANDS[which]
    known = recipes(justfile)
    rows = []
    for name in names:
        recipe = known[name]
        params = " ".join(
            (
                f"[{p['name']}]"
                if p["default"] is not None or p["kind"] != "singular"
                else f"<{p['name']}>"
            )
            for p in recipe["parameters"]
        )
        said = first_sentence(comment(justfile, name))
        if len(done := steps(recipe)) > 1:
            said += " Steps: " + ", ".join(done) + "."
        rows.append((f"just {name} {params}".strip(), said))
    width = max(len(left) for left, _ in rows)
    return (
        "```bash\n"
        + "\n".join(f"{left:<{width}}  # {said}" for left, said in rows)
        + "\n```\n"
    )


def screens() -> str:
    table = (ROOT / "frontend/lib/features/game/domain/screen_table.dart").read_text()
    listed = ", ".join(
        f"{n} {t}" for _, n, t in re.findall(r"(\w+)\('(\d\d\w?)', '([^']+)'\)", table)
    )
    sweep = (ROOT / "frontend/test/helpers/screen_sweep.dart").read_text()
    sizes = re.search(r"const sweepSizes = \[(.*?)\];", sweep, re.S)[1]
    sizes = ", ".join(f"{w}x{h}" for w, h in re.findall(r"Size\((\d+), (\d+)\)", sizes))
    scales = re.search(r"const sweepScales = \[([^\]]*)\]", sweep)[1]
    pictures = (ROOT / "tool/handover_pictures.py").read_text()
    drawn = ", ".join(
        f"{w}x{h}"
        for w, h in re.findall(
            r"\((\d+), (\d+)\)", re.search(r"^SIZES = (.*)$", pictures, re.M)[1]
        )
    )
    look = re.search(
        r'^look state width="(\d+)" height="(\d+)"',
        (ROOT / "frontend/justfile").read_text(),
        re.M,
    )
    strict = sorted(
        {
            args[0]
            for check in github_checks.required_checks(ROOT)
            for r, args in check.recipes
            if r == "screens" and args[1:] == ("strict",)
        }
    )
    return (
        f"The screens (`AppScreen`, `frontend/lib/features/game/domain/screen_table.dart`): {listed}.\n"
        f"Every state is swept at {sizes}, text at {scales.replace(', ', ', ')}\n"
        "(`sweepSizes`, `sweepScales` in `frontend/test/helpers/screen_sweep.dart`).\n"
        f"GitHub draws every state strict at {' and '.join(strict)} wide (`just screens {strict[0]} strict`);\n"
        f"`just look <state>` shows one at {look[1]}x{look[2]}; `just handover` draws what a change reaches at {drawn}.\n"
    )


def checks() -> str:
    rows = ["| Check (the job's name) | Runs |", "|---|---|"]
    for check in github_checks.required_checks(ROOT):
        ran = ", ".join(f"`just {' '.join((r, *a))}`" for r, a in check.recipes)
        rows.append(f"| `{check.name}` | {ran} |")
    return "\n".join(rows) + "\n"


def agents() -> str:
    rows = ["| Agent | Model, effort | Tools |", "|---|---|---|"]
    for path in sorted((ROOT / ".claude/agents").glob("*.md")):
        front = dict(
            re.findall(r"^(\w+): (.*)$", path.read_text().split("---")[1], re.M)
        )
        rows.append(
            f"| `{front['name']}` | {front['model']}, {front['effort']} | {front['tools']} |"
        )
    return "\n".join(rows) + "\n"


BLOCKS = {
    "commands root": lambda: commands("root"),
    "commands backend": lambda: commands("backend"),
    "commands frontend": lambda: commands("frontend"),
    "screens": screens,
    "checks": checks,
    "agents": agents,
}


def main(argv: list[str]) -> int:
    fix, stale = "--fix" in argv, []
    for document in DOCUMENTS:
        path = ROOT / document
        text = path.read_text()

        def fill(m: re.Match) -> str:
            name = m["name"]
            if name not in BLOCKS:
                stale.append(
                    f"{document}: no generated block is called '{name}' (known: {', '.join(BLOCKS)})"
                )
                return m[0]
            body = BLOCKS[name]()
            if body != m["body"]:
                stale.append(
                    f"{document}: the '{name}' block is not what the code says. Fix: tool/gen_docs.py --fix"
                )
            return m[1] + body + m[4]

        new = BLOCK.sub(fill, text)
        if fix and new != text:
            path.write_text(new)
            print(f"gen_docs: rewrote {document}")
    if fix:
        return 0
    for line in stale:
        print(line, file=sys.stderr)
    return 1 if stale else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
